mapper.select:
SELECT 
FROM contest c

WHERE c.contest_id = #{contestId}

SELECT 
FROM contest c

WHERE 1 = 1

    AND c.status = #{status}


    AND c.contest_type = #{contestType}


    AND c.requester_company_user_id = #{requesterCompanyUserId}

ORDER BY FIELD(c.status, 'OPEN', 'ENDED'), c.deadline_at ASC, c.created_at DESC
LIMIT #{limit}

SELECT FROM contest_open_request cor JOIN user_account u ON u.user_id = cor.requester_user_id LEFT JOIN company_application ca ON ca.user_id = cor.requester_user_id LEFT JOIN user_account reviewer ON reviewer.user_id = cor.reviewed_by WHERE 1 = 1
AND cor.status = #{status}
ORDER BY FIELD(cor.status, 'PENDING', 'REJECTED', 'APPROVED'), cor.created_at DESC LIMIT #{limit}

SELECT COUNT(*)
FROM contest_save
WHERE contest_id = #{contestId}
  AND user_id = #{userId}

mapper.delete:
DELETE FROM contest_save
WHERE contest_id = #{contestId}
  AND user_id = #{userId}

mapper.update:
UPDATE contest c
SET c.save_count = (
  SELECT COUNT(*) FROM contest_save cs WHERE cs.contest_id = #{contestId}
)
WHERE c.contest_id = #{contestId}
